style.css:
@-moz-document domain("roblox.com") {
body {
        background-color: #0a0a0a !important; /* fundo preto escuro */
        color: #ff66cc !important; /* letras rosas */
    }

    a, a * {
        color: #ff66cc !important; /* links em rosa */
        text-decoration: none !important;
        transition: color 0.3s ease;
    }

    a:hover, a:hover * {
        color: #ff0000 !important; /* ao passar o mouse fica vermelho */
    }

    header, nav, .navbar, .topbar {
        background-color: #0a0a0a !important;
    }

    .container, .content {
        background-color: #121212 !important; /* tom um pouco diferente para contraste */
    }

    input, textarea, select, button {
        background-color: #1c1c1c !important;
        color: #ff66cc !important;
        border: 1px solid #333 !important;
    }

    ::selection {
        background: #ff66cc;
        color: #0a0a0a;
    }
}
